static String translate(String text){if(text==null||text.length()>1600)return text;String hit=CACHE.get(text);if(hit!=null)return hit;String plain=text.replaceAll("@[a-zA-Z0-9]{3}@|<[^>]*>","").trim();Matcher word=Pattern.compile("^[A-Za-z]+").matcher(plain);String prefix=word.find()?word.group().toLowerCase(Locale.ROOT):"";String result=apply(RULES.get(prefix),text);if(result==null&&!prefix.isEmpty()&&Pattern.compile("(?i)\\b(?:has|have|you|your|there|cannot|need|requires|completed|received|found|killed|sent|is|are|was|were|the|with|for|from|level|levels|melee|ranged|magic|defence|strength|prestige|points|kills|remaining|damage|total|amount|chance)\\b").matcher(plain).find())result=apply(RULES.get(""),text);if(result==null)result=text;CACHE.put(text,result);return result;}
 private static String apply(List<Rule> rules,String text){if(rules==null)return null;for(Rule r:rules){Matcher m=r.p.matcher(text);if(!m.matches())continue;String[] values=new String[r.skills.length];for(int i=0;i<r.slots.length;i++){int slot=r.slots[i];String value=m.group(i+1);if(slot<r.skills.length&&r.skills[slot])value=PtBr.skill(value);values[slot]=value;}Matcher tokens=Pattern.compile("\\{([0-9]+)\\}").matcher(r.t);StringBuffer out=new StringBuffer();while(tokens.find()){int slot=Integer.parseInt(tokens.group(1));tokens.appendReplacement(out,Matcher.quoteReplacement(slot<values.length?values[slot]:tokens.group()));}tokens.appendTail(out);return out.toString();}return null;}
